//! `cap_title` — pure title-length capping (per-method record of the pty_faults parser).

use super::TITLE_CAP;

/// Cap a fault title at [`TITLE_CAP`] bytes, on a char boundary, appending an ellipsis when trimmed —
/// so a monster single-line log entry can't bloat a DB row.
pub(crate) fn cap_title(t: &str) -> String {
    if t.len() <= TITLE_CAP {
        t.to_string()
    } else {
        // Cap on a char boundary at or below the byte cap.
        let mut end = TITLE_CAP;
        while end > 0 && !t.is_char_boundary(end) {
            end -= 1;
        }
        format!("{}\u{2026}", &t[..end])
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn short_titles_pass_through_unchanged() {
        assert_eq!(cap_title("boom"), "boom");
        assert_eq!(cap_title(""), "");
    }

    #[test]
    fn long_titles_are_capped_with_an_ellipsis() {
        let long = "x".repeat(TITLE_CAP + 50);
        let out = cap_title(&long);
        assert!(out.ends_with('\u{2026}'), "capped titles end with an ellipsis");
        assert!(out.len() <= TITLE_CAP + '\u{2026}'.len_utf8(), "no longer than the cap plus the ellipsis");
    }
}
